				myCh->signal[C_SIG_MODULE_FAULT] = P0; //kjhw_170906
				myData->mData.signal[M_SIG_DATA_SAVE_ERROR] = P0; //jhkw_190830
				myData->mData.signal[M_SIG_DATA_SAVE_ERROR_PHASE] = P0; //jhkw_190830
				cPause_sig_continue(ch);
