#ifdef __COA__
#if defined __COA_VER_100B__ || defined __COA_VER_100B2__
				cPause_sig_chamber_continue_1(ch);
#else //COA_VER_100C~
				cPause_sig_chamber_continue_2(ch);
#endif
#endif

#ifdef __COC__
#ifdef __COC_VER_1005__
				cPause_sig_chamber_continue_1(ch);
#else //COC_VER_1006, COC_VER_1007
				cPause_sig_chamber_continue_2(ch);
#endif
#endif
				break;
