void cEndCond_Aux(int ch)
{
	short int idxStepNo;
    int endCode=0, i, j;
	int idx;	//jhkw_190120
	long val, val2;

	if(myData->ChAttribute[ch].chNo_master == 0) return;
	if(myPs->config.installedTemp == 0
		&& myPs->config.installedAuxV == 0
		&& myPs->config.installedTH == 0) return; //kjh_160610

#ifdef __COA_VER_100B__
	if(myCh->misc.checkDelayTime < myPs->misc.increment_period * 40) return;
#else //COA_VER_100B2~
	if(time_cal_compare(COMP_LESS_THAN,
		myCh->misc.checkDelayTime_day, myCh->misc.checkDelayTime,
		0, myPs->misc.increment_period * 40) > 0) {
		return;
	}
#endif

	if(myCh->op.stepType == STEP_CYCLE || myCh->op.stepType == STEP_LOOP) {
		return;
	}

	idxStepNo = myCh->op.idxStepNo;

	for(i=0; i < MAX_AUX_DATA; i++) {
		if((ch+1) != myData->auxSetData[i].chNo) continue;

		j = myData->auxSetData[i].auxChNo - 1;

		if(myData->auxSetData[i].auxType == 0) { //temperature
			val2 = myData->COM.com_port[AUX_TEMP].value[j];

			if(cEndCond_Aux_step(ch, (int)idxStepNo, val2, i) > C_CD_NONE) {
				cRPT_SOC(idxStepNo);//20181219 KHK
				return;
			}

			val = myData->auxSetData[i].end_upper;
			endCode = aux_cCodeCheck(ch, C_CD_AUX_END_UPPER_TEMP,
				myData->COM.com_port[AUX_TEMP].value[j], val);
			if(endCode > C_CD_NONE) {
				myCh->misc.active_code = endCode;
				myCh->misc.active_division = ACTIVE_DIV_NEXT;
				cRPT_SOC(idxStepNo);//20181219 KHK
				return;
			}

			val = myData->auxSetData[i].end_lower;
			endCode = aux_cCodeCheck(ch, C_CD_AUX_END_LOWER_TEMP,
				myData->COM.com_port[AUX_TEMP].value[j], val);
			if(endCode > C_CD_NONE) {
				myCh->misc.active_code = endCode;
				myCh->misc.active_division = ACTIVE_DIV_NEXT;
				cRPT_SOC(idxStepNo);//20181219 KHK
				return;
			}
		} else if((myData->auxSetData[i].auxType == 1) //voltage
			|| (myData->auxSetData[i].auxType == 2)) { //kjh_160610 thermistor

			j = myData->aux_ch_num[j].daq_ch; //jhkw_201117
			val2 = myData->SubSensV.ch[j].sensV;

			//jhkw_190120s
			idx = IDX_LOC_OBJ_CELL_BALANCING_FLAG;
			if(myTestCond->local_object[idxStepNo][idx] == P1
				&& myData->auxSetData[i].auxType == 1){
				return;
			}
			//jhkw_190120e
			if(cEndCond_Aux_step(ch, (int)idxStepNo, val2, i) > C_CD_NONE) {
				cRPT_SOC(idxStepNo);//20181219 KHK
				return;
			}
/*
			val = myData->SubSensV.ch[j].sensV;
			if(myData->auxSetData[i].function_div == AUX_V_FUNC_DIV_ALL
				|| myData->auxSetData[i].function_div == AUX_V_FUNC_DIV_UPPER) {
				endCode = loc_cCodeCheck(ch, C_CD_AUX_END_UPPER_V_BRANCH,
					val, 1);
				if(endCode > C_CD_NONE) {
					myCh->misc.active_code = endCode;
					idx = IDX_LOC_OBJ_END_AUX_V_UPPER_BRANCH;
					myCh->misc.active_division
						= (short int)myTestCond->local_object[idxStepNo][idx];
					return;
				}
			}

			if(myData->auxSetData[i].function_div == AUX_V_FUNC_DIV_ALL
				|| myData->auxSetData[i].function_div == AUX_V_FUNC_DIV_LOWER) {
				endCode = loc_cCodeCheck(ch, C_CD_AUX_END_LOWER_V_BRANCH,
					val, 1);
				if(endCode > C_CD_NONE) {
					myCh->misc.active_code = endCode;
					idx = IDX_LOC_OBJ_END_AUX_V_LOWER_BRANCH;
					myCh->misc.active_division
						= (short int)myTestCond->local_object[idxStepNo][idx];
					return;
				}
			}
*/
			val = myData->auxSetData[i].end_upper;
			endCode = aux_cCodeCheck(ch, C_CD_AUX_END_UPPER_V,
				myData->SubSensV.ch[j].sensV, val);
			if(endCode > C_CD_NONE) {
				//jhkw_190705s
				if(myData->auxSetData[i].auxType == 2) {//Th
					endCode = C_CD_AUX_END_UPPER_TEMP;
				}
				//jhkw_190705e
				myCh->misc.active_code = endCode;
				myCh->misc.active_division = ACTIVE_DIV_NEXT;
				cRPT_SOC(idxStepNo);//20181219 KHK
				return;
			}

			val = myData->auxSetData[i].end_lower;
			endCode = aux_cCodeCheck(ch, C_CD_AUX_END_LOWER_V,
				myData->SubSensV.ch[j].sensV, val);
			if(endCode > C_CD_NONE) {
				//jhkw_190705s
				if(myData->auxSetData[i].auxType == 2) {//Th
					endCode = C_CD_AUX_END_LOWER_TEMP;
				}
				//jhkw_190705e
				myCh->misc.active_code = endCode;
				myCh->misc.active_division = ACTIVE_DIV_NEXT;
				cRPT_SOC(idxStepNo);//20181219 KHK
				return;
			}
		}
	}
}

