int cEndCond_Can_default(int ch, float f_val2, int can_idx)
{
	int rtnCode;
	float f_val;

	switch(myData->AppControl.config.systemModel) {
		case C_DAEWOO_450V_200A_10A_90KW: //kjg_091112_w
		case C_DAEWOO_450V_200A_10A_90KW_2:
		case C_DAEWOO_450V_200A_50A_90KW:	//kjh_150518
		case C_DAEWOO_450V_200A_50A_90KW_2:	//jhk_150710
			f_val2 *= 1000.0;
			break;
		default:
			//kjg_101221 f_val2 *= 1000000.0;
			break;
	}

	f_val = myData->canReceiveSetData.normalData[ch][can_idx].end_upper;
	rtnCode = can_cCodeCheck(ch, C_CD_CAN_END_UPPER, f_val2, f_val);
	if(rtnCode > C_CD_NONE) {
		myCh->misc.active_code = rtnCode;
		myCh->misc.active_division = ACTIVE_DIV_NEXT;
		return rtnCode;
	}

	f_val = myData->canReceiveSetData.normalData[ch][can_idx].end_lower;
	rtnCode = can_cCodeCheck(ch, C_CD_CAN_END_LOWER, f_val2, f_val);
	if(rtnCode > C_CD_NONE) {
		myCh->misc.active_code = rtnCode;
		myCh->misc.active_division = ACTIVE_DIV_NEXT;
		return rtnCode;
	}

	return C_CD_NONE;
}

void cUserControl(int ch)
{
	short int func_div, func_div1, func_div2, func_div3;
	int i, j, can_ch;

	if(myData->ChAttribute[ch].chNo_master == 0) return;
	if(myPs->config.installedCAN == 0) return;

//jhkw_151106s
#ifdef __COA__
	switch(myData->mData.config.division_CAN) { //kjhw_140620
		case 1:
			can_ch = ch;
			break;
		default:
			if(ch == 0) can_ch = 0;
			else can_ch = 2;
			break;
	}
#else
	if(ch == 0) can_ch = 0;
	else can_ch = 2;
#endif
//jhkw_151106e	
	for(i=0; i < (myData->canReceiveDataCount[ch][0]
		+ myData->canReceiveDataCount[ch][1]); i++) {
		if(myData->canReceiveSetData.normalData[ch][i].canType == 0) continue;

		func_div = CAN_RX_FUNC_DIV_NONE;
		func_div1 = myData->canReceiveSetData.normalData[ch][i].function_div;
		func_div2 = myData->canReceiveSetData.normalData[ch][i].function_div2;
		func_div3 = myData->canReceiveSetData.normalData[ch][i].function_div3;
		if(func_div1 >= CAN_RX_FUNC_USER_RUN
			&& func_div1 <= CAN_RX_FUNC_USER_GOTO) {
			func_div = func_div1;
		} else {
			if(func_div2 >= CAN_RX_FUNC_USER_RUN
				&& func_div2 <= CAN_RX_FUNC_USER_GOTO) {
				func_div = func_div2;
			} else {
				if(func_div3 >= CAN_RX_FUNC_USER_RUN
					&& func_div3 <= CAN_RX_FUNC_USER_GOTO) {
					func_div = func_div3;
				} else {
					continue;
				}
			}
		}

		if(func_div == CAN_RX_FUNC_USER_RUN) {
			continue;
		} else if(func_div == CAN_RX_FUNC_USER_STOP) {
			if(myCh->op.state == C_RUN || myCh->op.state == C_PAUSE) {
				if(cUserControl_can_stop(ch, i) < 0) continue;
			} else continue;
		} else if(func_div == CAN_RX_FUNC_USER_PAUSE) {
			if(myCh->op.state == C_RUN) {
				if(cUserControl_can_pause(ch, i) < 0) continue;
			} else continue;
		} else if(func_div == CAN_RX_FUNC_USER_CONTINUE) {
			if(myCh->op.state == C_PAUSE) {
				if(cUserControl_can_continue(ch, i) < 0) continue;
			} else continue;
		} else if(func_div == CAN_RX_FUNC_USER_NEXT) {
			if(myCh->op.state == C_RUN || myCh->op.state == C_PAUSE) {
				if(cUserControl_can_next(ch, i) < 0) continue;
			} else continue;
		} else if(func_div == CAN_RX_FUNC_USER_GOTO) {
			if(myCh->op.state == C_RUN || myCh->op.state == C_PAUSE) {
				if(cUserControl_can_goto(ch, i) < 0) continue;
			} else continue;
		}

		break;
	}

//jhkw_151106s
	if(myCh->op.stepType == STEP_EXTERNAL_CAN
		|| myCh->op.stepType == STEP_REST
		|| myCh->op.stepType == STEP_EXTERNAL_CAN_2) {
		if(myData->CAN.signal[can_ch][CAN_SIG_USER_NEXT] == P1) {
			if(myCh->op.state == C_RUN || myCh->op.state == C_PAUSE) {
				if(myCh->signal[C_SIG_CMD_NEXT_STEP] == P0) {
					myCh->signal[C_SIG_CMD_NEXT_STEP] = P1;
					for(i=0; i < 3; i++) {
						j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
						if(j >= 0) {
							myData->cData[j].signal[C_SIG_CMD_PAUSE] = P1;
						}
					}
				}
			}
			myData->CAN.signal[can_ch][CAN_SIG_USER_NEXT] = P0;
		}
	}
//jhkw_151106e
	if(myCh->op.stepType == STEP_EXTERNAL_CAN //kjhw_131206
		|| myCh->op.stepType == STEP_EXTERNAL_CAN_2) { //kjg_140916
		//kjhw_131011s
		if(myData->testCond[ch].external_data[1].control == 0) {
		} else if(myData->testCond[ch].external_data[1].control == 1) {
		} else if(myData->testCond[ch].external_data[1].control == 2) {
			if(myCh->op.state == C_RUN) {
				if(myCh->signal[C_SIG_CMD_PAUSE] == P0) {
					myCh->signal[C_SIG_CMD_PAUSE] = P1;
					for(i=0; i < 3; i++) {
						j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
						if(j >= 0) {
							myData->cData[j].signal[C_SIG_CMD_PAUSE] = P1;
						}
					}
				}
			}
		} else if(myData->testCond[ch].external_data[1].control == 3) {
			if(myCh->op.state == C_PAUSE) {
				if(myCh->signal[C_SIG_CMD_CONTINUE] == P0) {
					myCh->signal[C_SIG_CMD_CONTINUE] = P1;
					//for(i=0; i < 3; i++) {
					//	j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
					//	if(j >= 0) {
					//		myData->cData[j].signal[C_SIG_CMD_CONTINUE] = P1;
					//	}
					//}
				}
			}
		} else if(myData->testCond[ch].external_data[1].control == 4) {
			if(myCh->signal[C_SIG_CMD_STOP] == P0) {
				myCh->signal[C_SIG_CMD_STOP] = P1;
				for(i=0; i < 3; i++) {
					j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
					if(j >= 0) {
						myData->cData[j].signal[C_SIG_CMD_STOP] = P1;
					}
				}
			}
		} //kjhw_131011e
	}
}

int cUserControl_can_stop(int ch, int rx_idx)
{
	unsigned char tmp, tx_flag;
	int tx_idx, i, j, can_ch;
	S_RT_CAN_MSG can_msg;

	if(myData->CanData[ch][rx_idx].l_val[0] == 0) return -1;
	if(myCh->signal[C_SIG_CMD_STOP] != P0) return -2;

	myCh->signal[C_SIG_CMD_STOP] = P1;
	for(i=0; i < 3; i++) {
		j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
		if(j >= 0) {
			myData->cData[j].signal[C_SIG_CMD_STOP] = P1;
		}
	}

	for(tx_idx=0; tx_idx < (myData->canTransmitDataCount[ch][0]
		+ myData->canTransmitDataCount[ch][1]); tx_idx++) {
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div
			== CAN_TX_FUNC_USER_STOP) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div2
			== CAN_TX_FUNC_USER_STOP) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div3
			== CAN_TX_FUNC_USER_STOP) break;
	}
	if(tx_idx >= (myData->canTransmitDataCount[ch][0]
		+ myData->canTransmitDataCount[ch][1])) return -3;

	memset((char *)&can_msg, 0, sizeof(S_RT_CAN_MSG));

	can_msg.id = (unsigned int)myData->canTransmitSetData
		.normalData[ch][tx_idx].canID;
	can_msg.type = 0;
	if(myData->canTransmitSetData.normalData[ch][tx_idx].canType == CAN_MASTER)
		i = CAN_MASTER;
	else i = CAN_SLAVE;
	can_ch = ch * MAX_CAN_TYPE + (i - 1);
	can_msg.length = 3;

	j = myData->canTransmitSetData.normalData[ch][tx_idx].startBit;
	tmp = 0;
	for(i=0; i < 64; i++) {
		if((i % 8) == 0) {
			tmp = 0x01;
		}
		if((i >= j) && (i < (j + myData->canTransmitSetData
			.normalData[ch][tx_idx].bitCount))) {
			can_msg.data[i / 8] |= tmp;
		}
		tmp = tmp << 1;
	}

	for(tx_idx=0; tx_idx < (myData->canTransmitDataCount[ch][0]
		+ myData->canTransmitDataCount[ch][1]); tx_idx++) {
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div
			== CAN_TX_FUNC_USER_STATE1) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div2
			== CAN_TX_FUNC_USER_STATE1) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div3
			== CAN_TX_FUNC_USER_STATE1) break;
	}
	if(tx_idx >= (myData->canTransmitDataCount[ch][0]
		+ myData->canTransmitDataCount[ch][1])) tx_flag = 0;
	else tx_flag = 1;

	if(tx_flag == 1) {
		j = myData->canTransmitSetData.normalData[ch][tx_idx].startBit;
		for(i=0; i < 64; i++) {
			if((i >= j) && (i < (j + myData->canTransmitSetData
				.normalData[ch][tx_idx].bitCount))) {
				if(myCh->op.state == C_RUN) {
					can_msg.data[i / 8] = myCh->op.idxStepNo + 1;
				}
				break;
			}
		}
	}

	rt_can_write(can_ch, (char *)&can_msg);

	return 0;
}

int cUserControl_can_pause(int ch, int rx_idx)
{
	unsigned char tmp, tx_flag;
	int tx_idx, i, j, can_ch;
	S_RT_CAN_MSG can_msg;

	if(myData->CanData[ch][rx_idx].l_val[0] == 0) return -1;
	if(myCh->signal[C_SIG_CMD_PAUSE] != P0) return -2;

	myCh->signal[C_SIG_CMD_PAUSE] = P1; //kjg_w
/*	for(i=0; i < 3; i++) {
		j = (int)myData->ChAttribute[ch].chNo_slave[i] - 1;
		if(j >= 0) {
			myData->cData[j].signal[C_SIG_CMD_PAUSE] = P1;
		}
	}*/

	for(tx_idx=0; tx_idx < (myData->canTransmitDataCount[ch][0]
		+ myData->canTransmitDataCount[ch][1]); tx_idx++) {
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div
			== CAN_TX_FUNC_USER_PAUSE) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div2
			== CAN_TX_FUNC_USER_PAUSE) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div3
			== CAN_TX_FUNC_USER_PAUSE) break;
	}
	if(tx_idx >= (myData->canTransmitDataCount[ch][0]
		+ myData->canTransmitDataCount[ch][1])) return -3;

	memset((char *)&can_msg, 0, sizeof(S_RT_CAN_MSG));

	can_msg.id = (unsigned int)myData->canTransmitSetData
		.normalData[ch][tx_idx].canID;
	can_msg.type = 0;
	if(myData->canTransmitSetData.normalData[ch][tx_idx].canType == CAN_MASTER)
		i = CAN_MASTER;
	else i = CAN_SLAVE;
	can_ch = ch * MAX_CAN_TYPE + (i - 1);
	can_msg.length = 3;

	j = myData->canTransmitSetData.normalData[ch][tx_idx].startBit;
	tmp = 0;
	for(i=0; i < 64; i++) {
		if((i % 8) == 0) {
			tmp = 0x01;
		}
		if((i >= j) && (i < (j + myData->canTransmitSetData
			.normalData[ch][tx_idx].bitCount))) {
			can_msg.data[i / 8] |= tmp;
		}
		tmp = tmp << 1;
	}

	for(tx_idx=0; tx_idx < (myData->canTransmitDataCount[ch][0]
		+ myData->canTransmitDataCount[ch][1]); tx_idx++) {
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div
			== CAN_TX_FUNC_USER_STATE1) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div2
			== CAN_TX_FUNC_USER_STATE1) break;
		if(myData->canTransmitSetData.normalData[ch][tx_idx].function_div3
			== CAN_TX_FUNC_USER_STATE1) break;
	}
	if(tx_idx >= (myData->canTransmitDataCount[ch][0]
		+ myData->canTransmitDataCount[ch][1])) tx_flag = 0;
	else tx_flag = 1;

	if(tx_flag == 1) {
		j = myData->canTransmitSetData.normalData[ch][tx_idx].startBit;
		for(i=0; i < 64; i++) {
			if((i >= j) && (i < (j + myData->canTransmitSetData
				.normalData[ch][tx_idx].bitCount))) {
				if(myCh->op.state == C_RUN) {
					can_msg.data[i / 8] = myCh->op.idxStepNo + 1;
				}
				break;
			}
		}
	}

	rt_can_write(can_ch, (char *)&can_msg);

	return 0;
}

