		case C_SKI_500V_450A_200A_450KW_2:		//khj_200308
		case C_SKI_500V_450A_200A_450KW_3:		//khj_200308
		case C_SKI_500V_450A_200A_450KW_4:		//ktg_200410
		case C_SKI_500V_450A_200A_450KW_5:		//ktg_200410
		case C_SKI_500V_450A_200A_450KW_6:		//ktg_200410
		case C_SKI_1000V_400A_200A_100A_450KW:	//sec_230103
		case C_SKI_1000V_400A_200A_100A_450KW_2:	//sec_230426	//phb_240418
		case C_SKI_1000V_400A_200A_100A_450KW_3:	//phb_240418
		case C_SKI_1200V_500A_400A_300A_200A_600KW:     //phb_230116
		case C_SKI_1500V_350A_300A_200A_100A_450KW:     //phb_230117
		case C_SKI_AUX_BOX:					//shh_211007
			if(saveDt == 5) { //50ms //kjhw_180325s
				if(myCh->misc.sendDataCount == 0) {
					//COA_VER_100B2~
					if(time_cal_compare(COMP_EQUAL_TO, myCh->op.runTime_day,
						myCh->op.runTime, 0, 5) > 0) { //50ms
						rtn = 2; //save time(start)
						select = SAVE_FLAG_SAVING_TIME;
					}
				} else {
					if(saveDt != 0) {
						if(myCh->misc.sendDataCount == 1) {
							if(saveDt != 5) saveDt -= 5;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						} else if(myCh->misc.sendDataCount == 2) {
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
							}
						} else if(myCh->misc.sendDataCount == 3) { //kjg_170810
							saveDt = 5;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						}
					}
				}
			} else {
				if(myCh->misc.sendDataCount == 0) {
					//COA_VER_100B2~
					if(time_cal_compare(COMP_EQUAL_TO, myCh->op.runTime_day,
						myCh->op.runTime, 0, 10) > 0) { //100ms
						rtn = 2; //save time(start)
						select = SAVE_FLAG_SAVING_TIME;
					}
				} else {
					if(saveDt != 0) {
						if(myCh->misc.sendDataCount == 1) {
							if(saveDt != 10) saveDt -= 10;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						} else if(myCh->misc.sendDataCount == 2) {
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
							}
						} else if(myCh->misc.sendDataCount == 3) { //kjg_170810
							saveDt = 10;
							tmp = myCh->op.runTime - myCh->misc.saveDt;
							if(tmp >= saveDt) {
								rtn = 3; //save dT
								select = SAVE_FLAG_SAVING_TIME;
								myCh->misc.sendDataCount = 2;
							}
						}
					}
				}
			}
