					myCh->op.code = C_CD_FAULT_STOP_P;
					myCh->op.select = SAVE_FLAG_SAVING_END;
					myCh->misc.saveCode = myCh->op.code;
					send_save_msg(ch);
					myCh->signal[C_SIG_CMD_STOP] = P0;
					myCh->op.phase = P100;
