			switch(myData->AppControl.config.systemModel) {
				case C_LGC_5V_200A_75A_15A:
				//case C_TAESUNG_20V_600A_60A:
					//while cycle
					pattern_count++;
					//if(myTestCond->pattern[pattern_index][pattern_count].t_val
					if(myTestCond->pattern[pattern_count].t_val < 0) {
						myCh->misc.pattern_time_day = myCh->op.runTime_day;
						myCh->misc.pattern_time = myCh->op.runTime;
						myCh->misc.pattern_count = 1;
						pattern_count = 1;
					} else {
						myCh->misc.pattern_time_day = myCh->op.runTime_day;
						myCh->misc.pattern_time = myCh->op.runTime;
						myCh->misc.pattern_count++;
					}
					break;
				default:
					//1 cycle
					myCh->misc.pattern_time_day = myCh->op.runTime_day;
					myCh->misc.pattern_time = myCh->op.runTime;
					myCh->misc.pattern_count++;
					break;
			}
