	idx1 = (int)myTestCond->common_chCode[code].compIndex1;
	val1_b = myTestCond->common_object[idx1];

	switch(myTestCond->common_chCode[code].compType) {
		case COMP_NONE:
			rtn = 0;
			break;
		case COMP_LESS_THAN: //val1_a < val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a < val1_b) rtn = 1;
				else rtn = -1;
			}
			break;
		case COMP_LESS_THAN_OR_EQUAL_TO: //val1_a <= val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a <= val1_b) rtn = 2;
				else rtn = -1;
			}
			break;
		case COMP_GREATER_THAN: //val1_a > val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a > val1_b) rtn = 3;
				else rtn = -1;
			}
			break;
		case COMP_GREATER_THAN_OR_EQUAL_TO: //val1_a >= val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a >= val1_b) rtn = 4;
				else rtn = -1;
			}
			break;
		case COMP_EQUAL_TO: //val1_a = val1_b
			if(val1_b == 0) {
				rtn = -1;
			} else {
				if(val1_a == val1_b) rtn = 5;
				else rtn = -1;
			}
			break;
		case COMP_NOT_EQUAL_TO: //val1_a != val1_b	
			rtn = 0;
			break;
		default:
			rtn = 0;
			break;
	}
	if(rtn < 0) return 0;

	rtn = C_CD_NONE;
	myCh->misc.common_codeCount[code]++;
	if(myCh->misc.common_codeCount[code] >= count) {
		rtn = code + C_CD_COM_START;
	}

	return rtn;
