int bms_state_check_2(int ch)
{
	int fail_flag, group, rtn;
	long comp_v, key_voltage;
	unsigned long set_time;

	group = 0;
	fail_flag = 0;
	set_time = 10; //10ms * 10 = 100ms
	comp_v = 100000; //100mV
	rtn = 0;

	switch(myCh->signal[C_SIG_BMS_CHECK]) {
		case P0:
			myCh->signal[C_SIG_OUT_SWITCH] = P1;
			myCh->signal[C_SIG_SEMI_SWITCH] = P0;

			Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, ON); //SR_OPEN
			Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON); //SR_OPEN
			myCh->misc.ch_output_state = 0x00; //all_off

			myCh->misc.tmpDelayTime = 0;
			myCh->signal[C_SIG_BMS_CHECK]++;
			//myCh->signal[C_SIG_BMS_CHECK] = P6;
			break;
		case P1:
			myCh->misc.tmpDelayTime++;
			if((float)(myCh->misc.tmpDelayTime * 10)
				>= myData->canTransmitSetData.commonData[ch][0].value[4]) {
				myCh->misc.tmp_val[0][0] = myCh->op.Vsens;
				myCh->misc.tmp_val[1][0] = myCh->misc.Vinput;
				myCh->misc.tmp_val[2][0] = myCh->misc.Vpower;
				myCh->misc.tmp_val[3][0] = myCh->misc.Vbus;
				Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, ON); //SR_OPEN
				Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON); //SR_OPEN
				myCh->misc.ch_output_state = 0x01; //key_on

				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_BMS_CHECK]++;
			}
			break;
		case P2:
			myCh->misc.tmpDelayTime++;
			if((float)(myCh->misc.tmpDelayTime * 10)
				>= myData->canTransmitSetData.commonData[ch][0].value[1]) {
				myCh->misc.tmp_val[0][2] = myCh->op.Vsens;
				myCh->misc.tmp_val[1][2] = myCh->misc.Vinput;
				myCh->misc.tmp_val[2][2] = myCh->misc.Vpower;
				myCh->misc.tmp_val[3][2] = myCh->misc.Vbus;
				Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, ON); //SR_OPEN
				Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON); //SR_OPEN
				myCh->misc.ch_output_state = 0x00; //all_off

				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_BMS_CHECK]++;
			}
			break;
		case P3:
			myCh->misc.tmpDelayTime++;
			if((float)(myCh->misc.tmpDelayTime * 10)
				>= myData->canTransmitSetData.commonData[ch][0].value[4]) {
				myCh->misc.ch_output_state = 0x02; //charge_on

				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_BMS_CHECK]++;
			}
			break;
		case P4:
			myCh->misc.tmpDelayTime++;
			if((float)(myCh->misc.tmpDelayTime * 10)
				>= myData->canTransmitSetData.commonData[ch][0].value[1]) {
				myCh->misc.tmp_val[0][4] = myCh->op.Vsens;
				myCh->misc.tmp_val[1][4] = myCh->misc.Vinput;
				myCh->misc.tmp_val[2][4] = myCh->misc.Vpower;
				myCh->misc.tmp_val[3][4] = myCh->misc.Vbus;

				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_BMS_CHECK]++;
			}
			break;
		case P5:
			myCh->misc.tmpDelayTime++;
			if(myCh->misc.tmpDelayTime >= set_time) {
				myCh->misc.tmp_val[0][5] = myCh->op.Vsens;
				myCh->misc.tmp_val[1][5] = myCh->misc.Vinput;
				myCh->misc.tmp_val[2][5] = myCh->misc.Vpower;
				myCh->misc.tmp_val[3][5] = myCh->misc.Vbus;
				myCh->misc.ch_output_state = 0x00; //all_off

				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_BMS_CHECK]++;
			}
			break;
		case P6:
			myCh->misc.tmpDelayTime++;
			if((float)(myCh->misc.tmpDelayTime * 10)
				>= myData->canTransmitSetData.commonData[ch][0].value[4]) {
				//tmp_val : Vsens, Vinput, Vpower, Vbus
					//0 : sr_open, all_off
					//1 : sr_close, all_off -> unused
					//2 : sr_open, key_on
					//3 : sr_close, key_on -> unused
					//4 : sr_open, charge_on
					//5 : sr_close, charge_on -> sr_open, charge_on, 100ms delay
					
				key_voltage = myCh->misc.tmp_val[0][2];
				if(key_voltage < myCh->misc.tmp_val[0][4])
					key_voltage = myCh->misc.tmp_val[0][4];

				myCh->misc.internal_skip = 0;
				if(myCh->op.stepType == STEP_CHARGE) {
					if(key_voltage > (long)(myData->canTransmitSetData
						.commonData[ch][0].value[3] * 1000000.0)) {
						myCh->misc.internal_skip = 1;
					} else {
						if(myCh->misc.tmp_val[0][4]
							< (long)(myData->canTransmitSetData
							.commonData[ch][0].value[3] * 1000000.0 / 2.0)) {
						} else {
							myCh->misc.ch_output_state = 0x02; //charge_on
						}
					}
				} else if(myCh->op.stepType == STEP_DISCHARGE
					|| myCh->op.stepType == STEP_Z) {
					if(key_voltage < (long)(myData->canTransmitSetData
						.commonData[ch][0].value[2] * 1000000.0)) {
						myCh->misc.internal_skip = 1;
					} else {
						if(myCh->misc.tmp_val[0][2]
							< (long)(myData->canTransmitSetData
							.commonData[ch][0].value[2] * 1000000.0 / 2.0)) {
							myCh->misc.internal_skip = 1;
						} else {
							myCh->misc.ch_output_state = 0x01; //key_on
						}
					}
				} else {
					if(myCh->misc.tmp_ch_output_state == 0x01) {
						if(myCh->misc.tmp_val[0][4]
							< (long)(myData->canTransmitSetData
							.commonData[ch][0].value[3] * 1000000.0 / 2.0)) {
							myCh->misc.ch_output_state = 0x01; //key_on
						} else {
							myCh->misc.ch_output_state = 0x02; //charge_on
						}
					} else {
						if(myCh->misc.tmp_val[0][2]
							< (long)(myData->canTransmitSetData
							.commonData[ch][0].value[2] * 1000000.0 / 2.0)) {
							myCh->misc.ch_output_state = 0x02; //charge_on
						} else {
							myCh->misc.ch_output_state = 0x01; //key_on
						}
					}
					/*if(myCh->misc.tmp_val[0][2] > myCh->misc.tmp_val[0][4]) {
						myCh->misc.ch_output_state = 0x01; //key_on
					} else {
						myCh->misc.ch_output_state = 0x02; //charge_on
					}*/
				}
				myCh->misc.tmp_ch_output_state = myCh->misc.ch_output_state;

				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_BMS_CHECK]++;
			}
			break;
		case P7:
			myCh->misc.tmpDelayTime++;
			if((float)(myCh->misc.tmpDelayTime * 10)
				>= myData->canTransmitSetData.commonData[ch][0].value[1]) {
				switch(myCh->op.stepType) {
					case STEP_OCV:
					case STEP_REST:
					case STEP_LONG_TIME_REST:
						//SR_OPEN
						Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, ON);
						Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON);
						break;
					default:
						//SR_CLOSE
						Select_OutPoint(group, ch+1, O_CABLE_CHECK_SR, OFF);
						//SR_OPEN
						Select_OutPoint(1, ch+1, O_CABLE_CHECK_SR, ON);
						break;
				}

				myCh->misc.tmpDelayTime = 0;
				myCh->signal[C_SIG_BMS_CHECK] = P0;
				rtn = 1;
			}
			break;
		default:
			break;
	}

	return rtn;
}

