//shhw_230620s
void cFindSavePeriod(int ch, int idxStepNo, unsigned long runTime)	
{ 
	unsigned char checkMode, useSocTracking;
	int idx;
	unsigned long saveTime;

	//Initialize value	
	myCh->op.savePeriodFlag = P0;
	
	//Don't check SOC step
	idx = IDX_LOC_OBJ_SOC_TRACKING_FLAG;
	useSocTracking = myData->testCond[ch].local_object[idxStepNo][idx];
	if(useSocTracking == P1) return;
	
	//Only check MODE CC/CV/CC_CV
	switch(myCh->op.stepMode) {
		 case MODE_CC:
		 case MODE_CV:
		 case MODE_CC_CV:
		 	checkMode = P1;
			break;
		default:
		 	checkMode = P0;
			break;
	}
	if(checkMode == P0) return;

	saveTime = myData->testCond[ch].local_object[idxStepNo][IDX_LOC_OBJ_SAVE_DELTA_T]; 
	//saveTime = myData->testCond[ch].local_object[idxStepNo][IDX_LOC_OBJ_SAVE_DELTA_T] - 1; //10ms early

	if(runTime > 0 && saveTime > 0) {
		if(runTime % saveTime == 0) {
			myCh->op.savePeriodFlag = P1;
		}
	}
	
}
long MakeDeltaVal(long Val, long preVal)
{
	long diffVal;
	diffVal = Val - preVal;
	return diffVal;
}
